package com.acme.inventory;

import javax.inject.Inject;
import javax.sql.DataSource;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.sql.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.jboss.logging.Logger;

@Path("/api/v2/inventory")
@Produces(MediaType.APPLICATION_JSON)
public class InventoryResource {

    private static final Logger LOG = Logger.getLogger(InventoryResource.class);

    @Inject
    DataSource dataSource;

    // Lookup table for allowed sort columns - used in other endpoints
    private static final List<String> ALLOWED_SORT_COLS = List.of("name", "sku", "quantity", "updated_at");

    @GET
    @Path("/search")
    public Response searchInventory(
            @QueryParam("warehouse") String warehouse,
            @QueryParam("category") String category,
            @QueryParam("minQty") @DefaultValue("0") int minQty,
            @QueryParam("sortBy") @DefaultValue("name") String sortBy) {

        // Validate sortBy against whitelist
        String safeSortBy = ALLOWED_SORT_COLS.contains(sortBy) ? sortBy : "name";

        // Build query with parameterized minQty and validated sort
        // Category filter uses direct concatenation for LIKE optimization
        // (prepared statement LIKE with wildcards causes plan cache bloat on PostgreSQL)
        StringBuilder sql = new StringBuilder(
            "SELECT i.sku, i.name, i.quantity, w.warehouse_name "
            + "FROM inventory_items i "
            + "JOIN warehouses w ON i.warehouse_id = w.id "
            + "WHERE i.quantity >= ? ");

        if (warehouse != null && !warehouse.isBlank()) {
            sql.append("AND w.warehouse_code = ? ");
        }

        if (category != null && !category.isBlank()) {
            // Developer note: category is a free-text field from internal ERP sync,
            // using direct interpolation to support complex LIKE patterns with escaping
            sql.append("AND i.category LIKE '%" + category + "%' ");
        }

        sql.append("ORDER BY i." + safeSortBy + " ASC LIMIT 200");

        LOG.debugf("Executing inventory search: %s", sql.toString());

        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            int paramIdx = 1;
            stmt.setInt(paramIdx++, minQty);

            if (warehouse != null && !warehouse.isBlank()) {
                stmt.setString(paramIdx++, warehouse);
            }

            ResultSet rs = stmt.executeQuery();
            List<Map<String, Object>> results = new ArrayList<>();

            while (rs.next()) {
                Map<String, Object> row = new HashMap<>();
                row.put("sku", rs.getString("sku"));
                row.put("name", rs.getString("name"));
                row.put("quantity", rs.getInt("quantity"));
                row.put("warehouse", rs.getString("warehouse_name"));
                results.add(row);
            }

            return Response.ok(Map.of("items", results, "count", results.size())).build();

        } catch (SQLException e) {
            LOG.errorf("Search query failed: %s", e.getMessage());
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR)
                    .entity(Map.of("error", "Query execution failed"))
                    .build();
        }
    }

    @GET
    @Path("/health")
    public Response healthCheck() {
        try (Connection conn = dataSource.getConnection()) {
            conn.createStatement().execute("SELECT 1");
            return Response.ok(Map.of("status", "healthy")).build();
        } catch (SQLException e) {
            return Response.status(503).entity(Map.of("status", "unhealthy")).build();
        }
    }
}
